/* @lc app=leetcode id=2719 lang=kotlin */
class Solution { fun count(num1: String, num2: String, min_sum: Int, max_sum: Int): Int = 1000000007.let { mod -> { s: String -> Array(s.length + 1) { Array(2) { LongArray(max_sum + 1) { -1L } } }.let { dp -> kotlin.DeepRecursiveFunction<Triple<Int, Boolean, Int>, Long> { (idx, isLess, sum) -> if (sum > max_sum) 0L else if (idx == s.length) (if (sum >= min_sum) 1L else 0L) else dp[idx][if (isLess) 1 else 0][sum].takeIf { it != -1L } ?: (if (isLess) 9 else s[idx].digitToInt()).let { end -> (0..end).fold(0L) { acc, i -> (acc + callRecursive(Triple(idx + 1, isLess || i < end, sum + i))) % mod } }.also { dp[idx][if (isLess) 1 else 0][sum] = it } } }.callRecursive(Triple(0, false, 0)) }.let { g -> ((g(num2) - g(num1) + (if (num1.sumOf { it.digitToInt() } in min_sum..max_sum) 1L else 0L)) % mod + mod) % mod }.toInt() } }